"""CORE 표 중복 정의 정리 v1 (2026-10-18, 제이 «진행») — 10-18 조사 C2(.tmp/agentC2/)
① food_analyzer CORE_FOODS 리터럴에서 같은 키가 두 번 정의된 40개 — 파이썬 dict 는 뒤 정의가 이김 → 쓰이지 않던 «앞» 정의 40줄 삭제(값 불변)
   (어묵볶음 앞 130/500 vs 뒤 100/600 — 10-14 나트륨 자문 «600 유지»와 같은 뒤 정의가 원래 적용 중)
② gold 같은 검색키 충돌: 실사용 이름 영향 0 → 규칙 변경 없이 현재 결과 고정(R3 = 현행)
기대값은 정리 «전» 런타임 값으로 고정. 실행: python tools/tests/test_core_dedup_v1.py
"""
import os, sys, io, contextlib, ast
T = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
sys.path.insert(0, T)
with contextlib.redirect_stdout(io.StringIO()):
    import food_analyzer as fa
    fa.load_food_db()
fails, n = [], 0
def check(ok, msg):
    global n
    n += 1
    if not ok: fails.append(msg)
F = ('cal', 'prot', 'carbs', 'fat', 'fiber', 'sodium', 'sugar', 'serving')
EXP = {'훠궈': [70, 6.0, 4.0, 3.5, 1.0, 700, 1.0, 500], '삶은계란': [155, 13.0, 1.1, 11.0, 0, 124, 1.1, 60], '새우': [99, 24.0, 0.2, 0.3, 0, 111, 0, 100], '저지방우유': [46, 3.3, 5.0, 1.5, 0, 52, 5.0, 200], '두유': [54, 3.3, 6.3, 1.8, 0.6, 25, 3.0, 200], '호두': [654, 15.2, 13.7, 65.2, 6.7, 2, 2.6, 20], '아메리카노': [5, 0.3, 0.5, 0.0, 0, 5, 0, 355], '카페라떼': [38, 2.3, 3.5, 1.5, 0, 40, 3.5, 355], '바닐라라떼': [55, 2.0, 8.5, 1.5, 0, 45, 8.0, 355], '아이스티': [35, 0.0, 9.0, 0.0, 0, 5, 8.5, 355], '녹차라떼': [55, 2.0, 9.0, 1.5, 0.5, 35, 7.0, 355], '해물파전': [160, 7.0, 18.0, 7.0, 1.0, 550, 2.0, 150], '멸치볶음': [200, 18.0, 15.0, 8.0, 0.5, 800, 5.0, 30], '어묵볶음': [100, 5.0, 12.0, 3.5, 0.5, 600, 4.0, 80], '소세지볶음': [279.5, 11.95, 14.4, 19.35, 2.5, 886.76, 5.85, 100], '제육볶음': [190, 16.0, 8.0, 11.0, 1.0, 650, 4.0, 150], '갈비찜': [180, 15.0, 10.0, 9.0, 1.0, 500, 5.0, 200], '미역국': [25, 2.5, 2.0, 1.0, 1.0, 500, 0.3, 350], '갈비탕': [54.0, 8.51, 0.4, 2.06, 1.9, 199.0, 0.11, 500], '설렁탕': [55, 6.0, 1.0, 3.0, 0, 400, 0, 500], '곰탕': [60, 6.5, 1.0, 3.5, 0, 400, 0, 500], '순두부찌개': [45, 4.5, 3.0, 2.0, 0.5, 500, 1.0, 400], '부대찌개': [70, 5.0, 6.0, 3.0, 1.0, 700, 2.0, 400], '잡채': [120, 3.0, 18.0, 4.0, 1.5, 450, 5.0, 150], '당근': [41, 0.9, 9.6, 0.2, 2.8, 69, 4.7, 70], '오이': [15, 0.7, 3.6, 0.1, 0.5, 2, 1.7, 100], '토마토': [18, 0.9, 3.9, 0.2, 1.2, 5, 2.6, 150], '파프리카': [31, 1.0, 6.0, 0.3, 2.1, 4, 4.2, 100], '시금치': [23, 2.9, 3.6, 0.4, 2.2, 79, 0.4, 80], '상추': [15, 1.4, 2.8, 0.2, 1.3, 4, 0.8, 30], '감자': [77, 2.0, 17.5, 0.1, 2.2, 6, 0.8, 150], '양파': [40, 1.1, 9.3, 0.1, 1.7, 4, 4.2, 80], '마늘': [149, 6.4, 33.1, 0.5, 2.1, 17, 1.0, 10], '버섯': [22, 3.1, 3.3, 0.3, 1.0, 5, 2.0, 50], '콩나물': [34, 3.5, 4.5, 0.7, 1.5, 5, 1.0, 80], '옥수수': [86, 3.3, 19.0, 1.2, 2.7, 15, 3.2, 150], '고구마': [86, 1.6, 20.1, 0.1, 3.0, 55, 4.2, 150], '아보카도': [160, 2.0, 8.5, 14.7, 6.7, 7, 0.7, 70], '청경채': [13, 1.5, 2.2, 0.2, 1.0, 65, 1.2, 100], '미나리': [17, 2.1, 2.5, 0.3, 2.0, 45, 0.5, 50]}
for k, v in EXP.items():
    got = [fa.CORE_FOODS.get(k, {}).get(f) for f in F]
    check(got == v, f'D1 {k} 런타임 값 {got} ≠ {v}')
# 리터럴에 중복 키 0
src = open(os.path.join(T, 'food_analyzer.py'), encoding='utf-8').read()
for node in ast.walk(ast.parse(src)):
    if isinstance(node, ast.Assign) and any(getattr(x, 'id', None) == 'CORE_FOODS' for x in node.targets) and isinstance(node.value, ast.Dict):
        ks = [k.value for k in node.value.keys]
        check(len(ks) == len(set(ks)), f'D2 CORE_FOODS 리터럴 중복 키 {len(ks) - len(set(ks))}개')
CASES = [('토스트식빵', '토스트 식빵'), ('퓨어100유기농레몬생강즙', '퓨어 100 유기농 레몬 생강즙'), ('과채주스딸기주스', '과ㆍ채주스 딸기 주스'), ('라떼고구마라떼아이스iced', '라떼 고구마라떼 아이스(ICED)'), ('라떼딸기라떼아이스iced', '라떼 딸기라떼 아이스(ICED)'), ('아이스티new복숭아아이스티', '아이스티 NEW복숭아아이스티'), ('커피카라멜마끼아또아이스iced', '커피 카라멜 마끼아또 아이스(ICED)'), ('커피카라멜마끼아또핫hot', '커피 카라멜 마끼아또 핫(HOT)'), ('커피카페라떼핫hot', '커피 카페 라떼 핫(HOT)'), ('커피헤이즐넛아메리카노핫hot', '커피 헤이즐넛아메리카노 핫(HOT)'), ('프리미엄  백김치', '프리미엄 백김치'), ('덮밥  낙지', '덮밥 낙지'), ('덮밥  오징어', '덮밥 오징어'), ('비빔밥  돌솥', '비빔밥 돌솥'), ('우동  볶음', '우동볶음'), ('된장국  감자', '된장국 감자'), ('된장국  쑥', '된장국 쑥'), ('된장국  호박', '된장국 호박'), ('겉절이 배추', '겉절이 배추'), ('겉절이배추', '겉절이배추'), ('덮밥낙지', '덮밥낙지'), ('토스트 식빵', '토스트 식빵'), ('토스트(식빵)', '토스트(식빵)'), ('배추 겉절이', '배추겉절이'), ('낙지 덮밥', '낙지덮밥'), ('닭가슴살샐러드', '닭가슴살 샐러드'), ('감자 구이', '감자구이'), ('마늘종 무침', '마늘종무침'), ('커피 카페 라떼', '커피 카페 라떼'), ('커피카페라떼', '커피카페라떼')]
for nm, k in CASES:
    with contextlib.redirect_stdout(io.StringIO()):
        gk, _ = fa._search_gold(nm)
    check(gk == k, f'G {nm} → {gk} (그대로 {k})')
print(f'test_core_dedup_v1: {n - len(fails)}/{n} 통과')
for m in fails: print('  ✗', m)
sys.exit(1 if fails else 0)
